Map<MuscleGroup, List<Path>> _withAliases(
  Map<MuscleGroup, List<Path>> regions,
  Map<MuscleGroup, MuscleGroup> aliases,
) {
  for (final entry in aliases.entries) {
    regions[entry.key] = regions[entry.value]!;
  }
  return Map.unmodifiable(regions);
}

Path _region(List<Offset> points) => Path()..addPolygon(points, true);
